function computeAttrMult(
  variety?: string | null,
  color?: string | null,
  newOld?: string | null,
  spec?: string | null,
  condition?: string | null,
): number {
  return 1;
}

// Canonical attributes helper — returns genuine row attributes without synthetic fillers
function getMandiCanonicalAttrs(mandiName: string): {
  variety: string;
  color: string;
  newOld: string;
  spec: string;
  condition: string;
} {
  return {
    variety: "",
    color: "",
    newOld: "",
    spec: "",
    condition: "",
  };
}

// Attach canonical attributes for a mandi preserving exact real min/max and Excel fields
function enrichRowWithAttrs(row: {
  product: string;
  byproduct: string;
  emoji: string;
  rateType: string;
  arrival: string;
  min: number;
  max: number;
  trend: "up" | "down" | "stable";
  trendPct: number;
  mandiName: string;
  mandiCity: string;
  province: string;
  vertical?: string;
  variety?: string;
  color?: string;
  spec?: string;
  condition?: string;
  newOld?: string;
  moisture?: string;
  origin?: string;
  area?: string;
  date?: string;
  quality?: string;
}): RichRow {
  return {
    ...row,
    variety: row.variety || "",
    color: row.color || "",
    newOld: row.newOld || "",
    spec: row.spec || "",
    condition: row.condition || "",
    quality: row.quality || "",
    moisture: row.moisture || "",
    origin: row.origin || "",
    area: row.area || "",
    min: row.min,
    max: row.max,
  };
}

