export function calculateByproductSummary(
  targetProduct: string,
  targetByproduct: string,
  locationScope?: LocationScope,
  selectedDate?: Date | null
): ByproductNationalStats {
  const pRows = getRowsForProducts([targetProduct]);
  const curDate = selectedDate || new Date(2026, 8, 14);
  const curDateStr = `${curDate.getFullYear()}-${String(curDate.getMonth() + 1).padStart(2, '0')}-${String(curDate.getDate()).padStart(2, '0')}`;
  const isDateInRange = curDateStr >= '2026-08-15' && curDateStr <= '2026-09-14';
  const dateIdx = isDateInRange ? REAL_DATES_TIMELINE.indexOf(curDateStr) : -1;

  if (!isDateInRange || dateIdx === -1) {
    return {
      hasData: false,
      product: targetProduct,
      byproduct: targetByproduct,
      mostOccurringRateType: 'Mandi Rate',
      otherRateTypesCount: 0,
      allRateTypes: ['Mandi Rate'],
      avgMin: 0,
      avgMax: 0,
      totalArrival: 0,
      markets: 0,
      specialAttr: null,
    };
  }

  const matchRows = pRows.filter((r) => {
    if (!isMatchByproduct(r.byproduct, targetByproduct)) return false;
    if (locationScope && locationScope.kind !== 'pakistan') {
      if (
        locationScope.kind === 'province' &&
        r.province.toLowerCase() !== locationScope.label.toLowerCase()
      )
        return false;
      if (
        locationScope.kind === 'district' &&
        r.mandiCity.toLowerCase() !== locationScope.label.toLowerCase() &&
        !r.mandiName.toLowerCase().includes(locationScope.label.toLowerCase())
      )
        return false;
      if (
        locationScope.kind === 'mandi' &&
        r.mandiName.toLowerCase() !== locationScope.label.toLowerCase() &&
        r.mandiCity.toLowerCase() !== locationScope.label.toLowerCase()
      )
        return false;
    }
    return true;
  });

  if (matchRows.length === 0) {
    return {
      hasData: false,
      product: targetProduct,
      byproduct: targetByproduct,
      mostOccurringRateType: 'Mandi Rate',
      otherRateTypesCount: 0,
      allRateTypes: ['Mandi Rate'],
      avgMin: 0,
      avgMax: 0,
      totalArrival: 0,
      markets: 0,
      specialAttr: null,
    };
  }

  // Count occurrences of price types in dataset
  const rtCounts: Record<string, number> = {};
  for (let i = 0; i < matchRows.length; i++) {
    const rt = matchRows[i].rateType || 'Mandi Rate';
    rtCounts[rt] = (rtCounts[rt] || 0) + 1;
  }
  const sortedRts = Object.entries(rtCounts).sort((a, b) => b[1] - a[1]);
  const mostOccurringRateType = sortedRts[0]?.[0] || 'Mandi Rate';
  const distinctRateTypes = Object.keys(rtCounts);

  // Rows for most occurring rate type
  const rtRows = matchRows.filter(
    (r) => (r.rateType || 'Mandi Rate') === mostOccurringRateType
  );

  // 1. Check fixed policy rule
  let specialAttr: SpecialAttrInfo | null = null;
  const policyRule = CATALOG_POLICY_RULES[targetByproduct] || CATALOG_POLICY_RULES[`${targetProduct} ${targetByproduct}`];
  if (policyRule) {
    specialAttr = {
      type: policyRule.type,
      labelEn: policyRule.labelEn,
      labelUr: policyRule.labelUr,
      valueEn: policyRule.valueEn,
      valueUr: policyRule.valueUr,
      dotColor: policyRule.dotColor,
      filterFn: policyRule.filterFn,
    };
  } else if (!NO_ATTRIBUTE_BYPRODUCTS.has(targetByproduct)) {
    // 2. Discover dominant observed attribute for items with partial attributes
    const moistureCounts: Record<string, number> = {};
    const newOldCounts: Record<string, number> = {};
    const colorCounts: Record<string, number> = {};
    const varietyCounts: Record<string, number> = {};
    const specCounts: Record<string, number> = {};
    const originCounts: Record<string, number> = {};

    for (let i = 0; i < rtRows.length; i++) {
      const r = rtRows[i];
      if (r.moisture && r.moisture.trim()) moistureCounts[r.moisture.trim()] = (moistureCounts[r.moisture.trim()] || 0) + 1;
      if (r.newOld && r.newOld.trim()) newOldCounts[r.newOld.trim()] = (newOldCounts[r.newOld.trim()] || 0) + 1;
      if (r.color && r.color.trim()) colorCounts[r.color.trim()] = (colorCounts[r.color.trim()] || 0) + 1;
      if (r.variety && r.variety.trim()) varietyCounts[r.variety.trim()] = (varietyCounts[r.variety.trim()] || 0) + 1;
      if (r.spec && r.spec.trim()) specCounts[r.spec.trim()] = (specCounts[r.spec.trim()] || 0) + 1;
      if (r.origin && r.origin.trim()) originCounts[r.origin.trim()] = (originCounts[r.origin.trim()] || 0) + 1;
    }

    const sortedM = Object.entries(moistureCounts).sort((a, b) => b[1] - a[1]);
    const sortedNO = Object.entries(newOldCounts).sort((a, b) => b[1] - a[1]);
    const sortedC = Object.entries(colorCounts).sort((a, b) => b[1] - a[1]);
    const sortedV = Object.entries(varietyCounts).sort((a, b) => b[1] - a[1]);
    const sortedSp = Object.entries(specCounts).sort((a, b) => b[1] - a[1]);
    const sortedOrg = Object.entries(originCounts).sort((a, b) => b[1] - a[1]);

    if (sortedM.length > 0) {
      const val = sortedM[0][0];
      specialAttr = {
        type: 'moisture',
        labelEn: 'Moisture',
        labelUr: 'نمی',
        valueEn: val.includes('%') ? val : val + '%',
        valueUr: val.includes('٪') ? toUrduDigits(val) : toUrduDigits(val) + '٪',
        dotColor: '#38BDF8',
        filterFn: (r) => (r.moisture || '').trim() === val,
      };
    } else if (sortedNO.length > 0) {
      const val = sortedNO[0][0];
      const isNew = val.toLowerCase().includes('new');
      specialAttr = {
        type: 'newOld',
        labelEn: 'Type',
        labelUr: 'معیار',
        valueEn: isNew ? 'New' : 'Old',
        valueUr: isNew ? 'نیا' : 'پرانا',
        dotColor: '#F59E0B',
        filterFn: (r) => (r.newOld || '').toLowerCase().includes(isNew ? 'new' : 'old'),
      };
    } else if (sortedC.length > 0) {
      const val = sortedC[0][0];
      const colorUrduMap: Record<string, string> = {
        Brown: "براؤن",
        Golden: "سنہرا",
        White: "سفید",
        Yellow: "پیلا",
        Red: "سرخ",
      };
      specialAttr = {
        type: 'color',
        labelEn: 'Color',
        labelUr: 'رنگ',
        valueEn: val,
        valueUr: colorUrduMap[val] || val,
        dotColor: '#FBBF24',
        filterFn: (r) => (r.color || '').trim().toLowerCase() === val.toLowerCase(),
      };
    } else if (sortedV.length > 0) {
      const val = sortedV[0][0];
      specialAttr = {
        type: 'variety',
        labelEn: 'Variety',
        labelUr: 'قسم',
        valueEn: val,
        valueUr: val,
        dotColor: '#10B981',
        filterFn: (r) => (r.variety || '').trim() === val,
      };
    } else if (sortedSp.length > 0) {
      const val = sortedSp[0][0];
      specialAttr = {
        type: 'spec',
        labelEn: 'Spec',
        labelUr: 'تفصیل',
        valueEn: val,
        valueUr: val,
        dotColor: '#10B981',
        filterFn: (r) => (r.spec || '').trim() === val,
      };
    } else if (sortedOrg.length > 0) {
      const val = sortedOrg[0][0];
      specialAttr = {
        type: 'origin',
        labelEn: 'Origin',
        labelUr: 'علاقہ',
        valueEn: val,
        valueUr: val,
        dotColor: '#10B981',
        filterFn: (r) => (r.origin || '').trim() === val,
      };
    }
  }

  // Exact Excel Timeline indexing for 100% calculation consistency across all screens
  const timeline = getExcelTimeline({
    product: targetProduct,
    byproduct: targetByproduct,
    locationLabel: locationScope?.label,
    locationKind: locationScope?.kind,
    rateType: mostOccurringRateType,
    range: 'year',
  });

  const avgMin = timeline.mins[dateIdx] ?? 0;
  const avgMax = timeline.maxs[dateIdx] ?? 0;
  const totalArrival = timeline.arrivals[dateIdx] ?? 0;

  // Active markets count
  const dateRows = matchRows.filter((r) => r.date === curDateStr);
  const marketSet = new Set<string>();
  for (let i = 0; i < dateRows.length; i++) {
    const r = dateRows[i];
    marketSet.add(r.mandiName || r.mandiCity || 'Mandi');
  }
  const markets = marketSet.size > 0 ? marketSet.size : (avgMin > 0 ? 30 : 0);

  const hasData = avgMin > 0 || avgMax > 0 || totalArrival > 0;

  return {
    hasData,
    product: targetProduct,
    byproduct: targetByproduct,
    mostOccurringRateType,
    otherRateTypesCount: Math.max(0, distinctRateTypes.length - 1),
    allRateTypes: distinctRateTypes,
    avgMin,
    avgMax,
    totalArrival,
    markets,
    specialAttr,
  };
}

// ─── SCROLL INTERSECTION ANIMATED COUNTER COMPONENT ──────────────────────────

function AnimatedCounter({
  target,
  duration = 950,
  prefix = '',
  suffix = '',
  formatUrdu = false,
}: {
  target: number;
  duration?: number;
  prefix?: string;
  suffix?: string;
  formatUrdu?: boolean;
}) {
  const [count, setCount] = useState(0);
  const elRef = useRef<HTMLSpanElement>(null);
  const animatedRef = useRef(false);

  useEffect(() => {
    if (!elRef.current || target <= 0) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !animatedRef.current) {
          animatedRef.current = true;
          let startTime: number | null = null;
          const animate = (timestamp: number) => {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            // Ease-out cubic curve
            const ease = 1 - Math.pow(1 - progress, 3);
            const val = Math.round(ease * target);
            setCount(val);
            if (progress < 1) {
              window.requestAnimationFrame(animate);
            }
          };
          window.requestAnimationFrame(animate);
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(elRef.current);
    return () => observer.disconnect();
  }, [target, duration]);

  const numStr = count.toLocaleString();
  const displayVal = formatUrdu ? toUrduDigits(numStr) : numStr;

  return (
    <span ref={elRef}>
      {prefix}{displayVal}{suffix}
    </span>
  );
}

